#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int edgeCount = 2 * (n - 1);

    int *head = malloc((n + 1) * sizeof(int));
    int *to = malloc(edgeCount * sizeof(int));
    int *next = malloc(edgeCount * sizeof(int));

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }

    int idx = 0;
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        to[idx] = b;
        next[idx] = head[a];
        head[a] = idx++;

        to[idx] = a;
        next[idx] = head[b];
        head[b] = idx++;
    }

    int *parent = calloc(n + 1, sizeof(int));
    int *order = malloc(n * sizeof(int));
    int *stack = malloc(n * sizeof(int));
    int *subtree = malloc((n + 1) * sizeof(int));

    for (int i = 1; i <= n; i++) {
        subtree[i] = 1;
    }

    int top = 0;
    int orderSize = 0;

    stack[top++] = 1;
    parent[1] = -1;

    while (top > 0) {
        int v = stack[--top];
        order[orderSize++] = v;

        for (int e = head[v]; e != -1; e = next[e]) {
            int u = to[e];

            if (u != parent[v]) {
                parent[u] = v;
                stack[top++] = u;
            }
        }
    }

    int answer = n;

    for (int i = orderSize - 1; i >= 0; i--) {
        int v = order[i];
        int p = parent[v];

        if (p != -1) {
            subtree[p] += subtree[v];

            int diff = n - 2 * subtree[v];
            if (diff < 0) diff = -diff;

            if (diff < answer) {
                answer = diff;
            }
        }
    }

    printf("%d\n", answer);

    free(head);
    free(to);
    free(next);
    free(parent);
    free(order);
    free(stack);
    free(subtree);

    return 0;
}
